import logging
from socket import socket, AF_INET, SOCK_STREAM
from taf.hw.mcs.exception import SocketConnectFailed


class SocketConnection(object):

    def __init__(self, ip, port, timeout=30):
        self._ip = ip
        self._port = port
        self._timeout = timeout
        self._socket_connection = None

    def connect_socket(self):
        self._socket_connection = socket(AF_INET, SOCK_STREAM)
        self._socket_connection.settimeout(self._timeout)
        try:
            self._socket_connection.connect((self._ip, self._port))
            logging.info("socket connected to {}:{} successfully".format(self._ip, self._port))
        except Exception as err_info:
            raise SocketConnectFailed("socket connect to {}:{} fail, {}.".format(self._ip, self._port, err_info))

    def send_command(self, command):
        try:
            logging.debug("send command --> {}.".format(command))
            self._socket_connection.send(self._convert_command_to_byte(command))
        except Exception as e:
            raise SocketConnectFailed(e)

    @staticmethod
    def _convert_command_to_byte(command):
        if isinstance(command, str):
            command = command + '\r\n'
            return command.encode('utf-8')
        elif isinstance(command, bytes):
            return command

    def receive_command(self):
        try:
            received = self._socket_connection.recv(4096).decode('utf-8')
            logging.debug("received <-- {}".format(received))
            return received
        except Exception as e:
            raise SocketConnectFailed(e)

    def close_socket(self):
        self._socket_connection.close()
        logging.info("close socket")
